    )
    case said(text: String
    )
    case speechStarted
    case queued(count: UInt32, text: String
    )
    case replyStarted(text: String
    )
    case replyFinished
    case mute
    case unmute
    case speaker(on: Bool
    )
    case end
    /**
     * The other side's `call_end`: a reason fails it with the toast; none ends it silently.
     */
    case hungUp(reason: String?
    )
